/**
 * Sitemap generation.
 *
 * The sitemap used to be a static file regenerated by hand with a browser-console
 * script (Scripts/sitemap_generator.js), which shipped a literal, unevaluated
 * template string as a listing URL — so no property page was ever listed. This
 * module rebuilds the whole document from MongoDB on every cache miss instead.
 *
 * Rules enforced here:
 *   - every URL is the page's own canonical URL (built by lib/urls.js), so the
 *     sitemap never advertises a page that canonicalises somewhere else
 *   - listings that are noindex, unlisted, or canonicalised to another URL are
 *     dropped
 *   - the URL list is de-duplicated before serialising
 *   - no PDFs: a sitemap of HTML pages only
 */

var log = require('log4js').getLogger('sitemap');
var PropertyModel = require('../models/properties');
var urls = require('./urls');
var resourcePages = require('./resourcePages');
var forRentPages = require('./forRentPages');

var SITE_ORIGIN = urls.SITE_ORIGIN;

// sitemaps.org caps a single sitemap file at 50,000 URLs.
var MAX_URLS = 50000;
var CACHE_TTL_MS = 3600000; // 1 hour

// Properties with this status must never be exposed publicly. Mirrors the filter
// in routes/listing.js getListing() — anything it refuses to render must not be
// advertised here either.
var UNLISTED_STATUS = 'Not list property';

// Search facets worth indexing on their own. Each is written through
// buildPropertiesPath() so key order matches the canonical the page renders.
var RENTED_PROPERTY_TYPES = ['Condo', 'House', 'Townhouse', 'Penthouse'];
var FURNISHED_FACETS = ['Yes', 'No'];

// Pages that have no database representation.
var STATIC_PAGES = [
    { path: '/', priority: '1.00' },
    { path: '/owners', priority: '0.80' },
    { path: '/owners/list-properties', priority: '0.80' },
    { path: '/owners/tenant-placement', priority: '0.80' },
    { path: '/owners/property-management', priority: '0.80' },
    { path: '/tenants/services', priority: '0.80' },
    { path: '/tenants/forms', priority: '0.80' },
    { path: '/tenants/FAQ', priority: '0.80' },
    { path: '/about', priority: '0.80' },
    { path: '/about/profile', priority: '0.80' },
    { path: '/about/team', priority: '0.80' },
    { path: '/about/career', priority: '0.80' },
    { path: '/terms', priority: '0.50' },
    { path: '/property-management/', priority: '0.80' },
    { path: '/property-management-vancouver', priority: '0.80' },
    { path: '/property-management-north-vancouver', priority: '0.80' },
    { path: '/west-vancouver-property-management', priority: '0.80' },
    { path: '/richmond-property-management', priority: '0.80' },
    { path: '/property-management-coquitlam', priority: '0.80' },
    { path: '/property-management-burnaby', priority: '0.80' }
];

var cache = { xml: null, count: 0, builtAt: 0 };

function escapeXml(value) {
    return String(value == null ? '' : value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;');
}

/** W3C datetime, the format the sitemap protocol expects for <lastmod>. */
function toLastmod(value) {
    var date = value ? new Date(value) : null;
    if (!date || isNaN(date.getTime())) date = new Date();
    return date.toISOString().replace(/\.\d{3}Z$/, '+00:00');
}

/** Drop repeats, keeping the first occurrence (static pages outrank generated ones). */
function dedupe(entries) {
    var seen = {};
    return entries.filter(function (entry) {
        if (seen[entry.loc]) return false;
        seen[entry.loc] = true;
        return true;
    });
}

function dedupeStrings(values) {
    var seen = {};
    return values.filter(function (value) {
        var key = value.toLowerCase();
        if (seen[key]) return false;
        seen[key] = true;
        return true;
    });
}

/**
 * Should this property appear in the sitemap? Returns null when it should, or a
 * short reason string when it should not (used for the summary log line).
 */
function rejectionReason(property) {
    if (!property.propertyId && property.propertyId !== 0) return 'missing propertyId';
    if (property.status === UNLISTED_STATUS) return 'unlisted';
    if (property.seoRobots && property.seoRobots !== 'index') return 'noindex';
    // A per-property canonical override pointing elsewhere means this URL is a
    // duplicate of another page — advertising it would contradict the page itself.
    if (property.seoCanonical && property.seoCanonical.trim() &&
        property.seoCanonical.trim() !== urls.buildListingUrl(property)) {
        return 'canonicalised elsewhere';
    }
    return null;
}

function collectStaticEntries(now) {
    var entries = STATIC_PAGES.map(function (page) {
        return { loc: SITE_ORIGIN + page.path, lastmod: now, priority: page.priority };
    });

    Object.keys(resourcePages).forEach(function (slug) {
        entries.push({
            loc: SITE_ORIGIN + '/resources/' + slug,
            lastmod: now,
            priority: '0.60'
        });
    });

    return entries;
}

function collectSearchEntries(cities, now) {
    var entries = [];

    // Where a filter has a /for-rent/... landing page, that clean URL is the
    // canonical the page renders — advertising the query form instead would
    // point crawlers at a URL that immediately canonicalises elsewhere.
    function add(query, priority) {
        var landing = forRentPages.findByQuery(query);
        entries.push({
            loc: landing ? landing.url : urls.buildPropertiesUrl(query),
            lastmod: now,
            priority: priority
        });
    }

    add({ status: 'Available' }, '0.90');

    cities.forEach(function (city) {
        add({ city: city, status: 'Available' }, '0.80');
    });

    FURNISHED_FACETS.forEach(function (furnished) {
        add({ status: 'Available', furnished: furnished }, '0.64');
    });

    add({ status: 'Rented' }, '0.50');
    RENTED_PROPERTY_TYPES.forEach(function (type) {
        add({ status: 'Rented', typeOfProperty: type }, '0.40');
    });

    return entries;
}

function collectListingEntries(properties) {
    var entries = [];
    var skipped = {};

    properties.forEach(function (property) {
        var reason = rejectionReason(property);
        if (reason) {
            skipped[reason] = (skipped[reason] || 0) + 1;
            return;
        }
        entries.push({
            loc: urls.buildListingUrl(property),
            lastmod: toLastmod(property.createdAt),
            priority: property.status === 'Available' ? '0.70' : '0.50'
        });
    });

    return { entries: entries, skipped: skipped };
}

function serialise(entries) {
    var body = entries.map(function (entry) {
        return '<url>\n' +
            '  <loc>' + escapeXml(entry.loc) + '</loc>\n' +
            '  <lastmod>' + entry.lastmod + '</lastmod>\n' +
            '  <priority>' + entry.priority + '</priority>\n' +
            '</url>';
    }).join('\n');

    return '<?xml version="1.0" encoding="UTF-8"?>\n' +
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
        body + '\n' +
        '</urlset>\n';
}

/**
 * Build the sitemap from scratch. cb(err, { xml, count }).
 */
function buildSitemap(cb) {
    var now = toLastmod(Date.now());

    // Only offer a city facet when that city actually has available inventory —
    // an empty result page is a thin duplicate, not a page worth indexing.
    PropertyModel.distinct('city', { status: 'Available' }, function (err, rawCities) {
        if (err) return cb(err);

        var cities = dedupeStrings((rawCities || []).map(function (city) {
            return (city || '').toString().trim();
        }).filter(Boolean)).sort();

        PropertyModel
            .find({ status: { $ne: UNLISTED_STATUS } },
                  'propertyId address status createdAt seoRobots seoCanonical')
            .lean()
            .exec(function (findErr, properties) {
                if (findErr) return cb(findErr);

                var listings = collectListingEntries(properties || []);
                var entries = dedupe(
                    collectStaticEntries(now)
                        .concat(collectSearchEntries(cities, now))
                        .concat(listings.entries)
                );

                if (entries.length > MAX_URLS) {
                    log.warn('Sitemap has ' + entries.length + ' URLs, over the ' + MAX_URLS +
                        ' per-file limit; truncating. Split it into a sitemap index.');
                    entries = entries.slice(0, MAX_URLS);
                }

                log.info('Sitemap rebuilt: ' + entries.length + ' URLs (' +
                    listings.entries.length + ' listings, skipped ' +
                    JSON.stringify(listings.skipped) + ')');

                cb(null, { xml: serialise(entries), count: entries.length });
            });
    });
}

/**
 * Cached sitemap. Rebuilds at most once per CACHE_TTL_MS per worker process; if a
 * rebuild fails but a previous copy exists, the stale copy is served rather than
 * handing a crawler an error page.
 */
function getSitemap(cb) {
    if (cache.xml && Date.now() - cache.builtAt < CACHE_TTL_MS) {
        return cb(null, cache.xml);
    }

    buildSitemap(function (err, result) {
        if (err) {
            log.error('Failed to rebuild sitemap', err);
            if (cache.xml) return cb(null, cache.xml);
            return cb(err);
        }
        cache.xml = result.xml;
        cache.count = result.count;
        cache.builtAt = Date.now();
        cb(null, cache.xml);
    });
}

/** Force the next request to rebuild (used after a property is saved). */
function invalidateCache() {
    cache.builtAt = 0;
}

module.exports = {
    getSitemap: getSitemap,
    buildSitemap: buildSitemap,
    invalidateCache: invalidateCache
};
